package com.rikkeibank.customer.web; import com.rikkeibank.customer.domain.Customer;import com.rikkeibank.customer.service.CustomerService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.UUID;
@RestController @RequestMapping("/api/customers") public class CustomerController{private final CustomerService service;public CustomerController(CustomerService s){service=s;}@PostMapping @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.CREATED) View create(@Valid @RequestBody Request r){return view(service.create(r.fullName(),r.email(),r.phone(),r.nationalId(),r.dateOfBirth(),r.address()));}@GetMapping @PreAuthorize("hasRole('ADMIN')")Page<View> list(Pageable p){return service.list(p).map(CustomerController::view);}@GetMapping("/{id}") @PreAuthorize("hasRole('ADMIN') or (hasRole('CUSTOMER') and #id.toString() == authentication.tokenAttributes['customerId'])")View get(@PathVariable UUID id){return view(service.get(id));}@GetMapping("/me")@PreAuthorize("hasRole('CUSTOMER')")View me(@AuthenticationPrincipal Jwt jwt){return view(service.get(UUID.fromString(jwt.getClaimAsString("customerId"))));}@PutMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")View update(@PathVariable UUID id,@Valid @RequestBody Request r){return view(service.update(id,r.fullName(),r.email(),r.phone(),r.nationalId(),r.dateOfBirth(),r.address(),r.active()));}@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable UUID id){service.delete(id);}static View view(Customer c){return new View(c.getId(),c.getFullName(),c.getEmail(),c.getPhone(),c.getNationalId(),c.getDateOfBirth(),c.getAddress(),c.isActive(),c.getCreatedAt());}public record Request(@NotBlank String fullName,@Email String email,@NotBlank String phone,@NotBlank String nationalId,@Past LocalDate dateOfBirth,String address,boolean active){}public record View(UUID id,String fullName,String email,String phone,String nationalId,LocalDate dateOfBirth,String address,boolean active,Instant createdAt){}}

